import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const $=s=>document.querySelector(s), gameEl=$('#game');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x92968d); scene.fog=new THREE.FogExp2(0x92968d,.0095);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,260); camera.position.set(0,1.7,8);
const renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'high-performance'}); renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,1.5)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1; gameEl.appendChild(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xc3ccd0,0x3c4033,1.5);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffddb1,2.1);sun.position.set(-35,52,22);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mat=(color,rough=.9,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={ground:mat(0x4b4d3e),mud:mat(0x38382f),grass:mat(0x535744),stone:mat(0x77756b),darkStone:mat(0x45473f),wood:mat(0x493b2c),charred:mat(0x262724),roof:mat(0x3a3933),brick:mat(0x745f4e),metal:mat(0x303632,.62,.48),rust:mat(0x5e4433,.7,.25),leaf:mat(0x29372b),leaf2:mat(0x3d4833),trunk:mat(0x443b2d),canvas:mat(0x696b52),glass:new THREE.MeshStandardMaterial({color:0x171d1a,roughness:.5}),blood:new THREE.MeshStandardMaterial({color:0x421f1a,roughness:.8})};
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,10,8),cylGeo=new THREE.CylinderGeometry(1,1,1,8),coneGeo=new THREE.ConeGeometry(1,1,6);
function mesh(geo,material,x,y,z,sx=1,sy=1,sz=1,cast=true){let o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=cast;o.receiveShadow=true;scene.add(o);return o}
function block(x,y,z,sx,sy,sz,material=mats.stone){return mesh(boxGeo,material,x,y,z,sx,sy,sz)}
const colliders=[];
function obstacle(x,z,w,d,top=3){colliders.push({x,z,w,d,top})}
// War-torn ground and boundary
const terrain=mesh(new THREE.PlaneGeometry(180,180),mats.ground,0,-.18,0,1,1,1,false);terrain.rotation.x=-Math.PI/2;
for(let i=0;i<260;i++){let x=(Math.random()-.5)*118,z=(Math.random()-.5)*118,r=.35+Math.random()*1.5;let m=mesh(sphereGeo,Math.random()<.5?mats.mud:mats.grass,x,-.1+Math.random()*.01,z,r,.07,r*.7,false);m.rotation.y=Math.random()*3}
// Road, tracks, shell craters
const road=mesh(new THREE.PlaneGeometry(5,95),mats.mud,3,.005,0,1,1,1,false);road.rotation.x=-Math.PI/2;road.rotation.z=.12;
for(let i=0;i<13;i++){let x=(Math.random()-.5)*42,z=(Math.random()-.5)*48,r=.7+Math.random()*1.8;mesh(new THREE.CircleGeometry(r,14),mats.mud,x,.006,z,1,1,.62,false).rotation.x=-Math.PI/2;mesh(new THREE.TorusGeometry(r*.8,.08,5,16),mats.grass,x,.016,z,1,1,.62,false).rotation.x=-Math.PI/2}
// Ruined houses from modular walls and broken roofs
function house(x,z,w,d,h=4,ruin=false){let wallMat=Math.random()<.5?mats.brick:mats.stone;const y=h/2;block(x-w/2,y,z,w,h,d*.13,wallMat);block(x+w/2,y,z,w,h,d*.13,wallMat);block(x,y,z-d/2,w*.13,h,d,wallMat);if(!ruin){block(x,y+h/2,z,w+1,.32,d+1,mats.roof);for(let xx of [-w*.23,w*.23])block(x+xx,1.2,z-d/2-.08,.8,1.5,.18,mats.glass)}else{block(x-w*.25,h*.83,z,w*.5,.35,d,mats.roof);block(x+w*.42,1.5,z+d*.1,.38,2,.4,mats.charred);for(let j=0;j<5;j++)block(x+(Math.random()-.5)*w,.3+Math.random()*.25,z+(Math.random()-.5)*d,.3+Math.random(),.25,.25,mats.brick)}obstacle(x,z,w,d,h);}
house(-16,-11,11,9,5,true);house(-27,-3,8,7,4.2,true);house(18,-12,10,8,4.5,true);house(27,-3,9,7,4,false);house(-18,10,9,7,4,false);house(17,12,10,8,4,true);
// Bombed church with open nave and tower
block(-1,2,-23,18,4,1,mats.stone);block(-9,3,-23,2,6,2,mats.stone);block(-9,7,-23,4,.55,4,mats.roof);block(-9,9,-23,1,4,1,mats.darkStone);let spire=mesh(coneGeo,mats.roof,-9,12,-23,1.35,3.8,1.35);block(-1,3,-29,1,6,11,mats.darkStone);block(5,2,-23,2,4,1,mats.brick);obstacle(-4,-24,18,12,8);
// Trenches, connected zigzag, berms and plank duckboards
function trench(x,z,length,rot=0){let g=new THREE.Group();for(let i=-1;i<=1;i+=2){let b=new THREE.Mesh(boxGeo,mats.mud);b.position.set(i*1.25,.25,0);b.scale.set(.55,.65,length);b.castShadow=true;g.add(b);let berm=new THREE.Mesh(boxGeo,mats.grass);berm.position.set(i*1.75,.48,0);berm.scale.set(.5,.8,length);g.add(berm)}let floor=new THREE.Mesh(boxGeo,mats.wood);floor.position.y=-.12;floor.scale.set(2,.12,length);g.add(floor);g.position.set(x,0,z);g.rotation.y=rot;scene.add(g)}trench(-4,7,17,0);trench(-10,14,15,Math.PI/2);trench(4,17,17,.14);trench(9,8,18,Math.PI/2);
// Bunker and watch post
block(0,.6,25,11,2.3,7,mats.darkStone);block(0,1.8,21.4,5,1.1,.5,mats.metal);block(0,1.45,21.05,3.2,.35,.3,mats.charred);for(let x of [-3.6,3.6])block(x,.5,21.4,.4,1.4,.3,mats.metal);obstacle(0,25,11,7,3);
for(let x of [31,35]){block(x,2,19,.25,4,.25,mats.wood);block(x+2,2,19,.25,4,.25,mats.wood);block(x+1,4,19,2.5,.3,.3,mats.wood);block(x+1,1.9,19,2,.25,2,mats.wood)}block(33,5,19,3,.2,3,mats.wood);
// forest belt: varied pine trees
for(let i=0;i<80;i++){let x=(Math.random()-.5)*80,z=-42-Math.random()*20;if(Math.abs(x)<20&&z>-50)continue;let h=5+Math.random()*7;mesh(cylGeo,mats.trunk,x,h*.32,z,.32,h*.65,.32);for(let k=0;k<3;k++)mesh(coneGeo,k%2?mats.leaf:mats.leaf2,x,h*.43+k*h*.2,z,2.3-k*.46,h*.42,2.3-k*.46)}
for(let i=0;i<22;i++){let x=(Math.random()-.5)*88,z=35+Math.random()*17,h=5+Math.random()*6;mesh(cylGeo,mats.trunk,x,h*.3,z,.3,h*.6,.3);for(let k=0;k<3;k++)mesh(coneGeo,mats.leaf,x,h*.38+k*h*.21,z,2-k*.4,h*.43,2-k*.4)}
// Burnt-out tanks and wreckage
function tank(x,z,rot=0){let g=new THREE.Group();function part(geo,m,x,y,zz,sx,sy,sz){let o=new THREE.Mesh(geo,m);o.position.set(x,y,zz);o.scale.set(sx,sy,sz);o.castShadow=true;g.add(o);return o}part(boxGeo,mats.charred,0,1,0,4.6,1.35,2.7);part(boxGeo,mats.rust,0,1.9,0,2.5,.9,2.1);part(cylGeo,mats.metal,0,2.2,-1.7,.28,4,.28).rotation.x=Math.PI/2;for(let side of [-1,1]){part(boxGeo,mats.metal,side*2.35,.8,0,.35,1.3,2.8);for(let j=0;j<4;j++)part(cylGeo,mats.charred,side*2.55,.65,-1+j*.68,.48,.22,.48)}g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);obstacle(x,z,5,3.5,3)}tank(-24,20,.4);tank(23,5,-.5);
// Sandbags, crates and scattered debris
for(let i=0;i<55;i++){let x=(Math.random()-.5)*54,z=(Math.random()-.5)*54;if(Math.abs(x)<7&&Math.abs(z)<7)continue;let b=mesh(boxGeo,i%3?mats.wood:mats.stone,x,.3,z,.65+Math.random()*.7,.5,.5+Math.random()*.7);b.rotation.y=Math.random()*3;}
// Smoke columns as translucent layered ellipsoids; ash/rain particles
const smokeMat=new THREE.MeshBasicMaterial({color:0x3a3b37,transparent:true,opacity:.17,depthWrite:false});const smoke=[];for(let i=0;i<12;i++){let group=new THREE.Group();for(let j=0;j<5;j++){let p=new THREE.Mesh(sphereGeo,smokeMat);p.position.set((Math.random()-.5)*1.5,j*.8,(Math.random()-.5)*1.2);p.scale.set(1.3+Math.random(),1.4+Math.random(),1.2+Math.random());group.add(p)}group.position.set((Math.random()-.5)*48,1,-20+Math.random()*44);scene.add(group);smoke.push(group)}
const rainCount=1100,rainGeo=new THREE.BufferGeometry(),rainPos=new Float32Array(rainCount*3);for(let i=0;i<rainCount;i++){rainPos[i*3]=(Math.random()-.5)*95;rainPos[i*3+1]=Math.random()*30;rainPos[i*3+2]=(Math.random()-.5)*95}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0xaeb8b7,size:.055,transparent:true,opacity:.42}));scene.add(rain);
// Distant fires
const fires=[];for(const [x,z] of [[-18,-10],[18,-12],[-25,19]]){let light=new THREE.PointLight(0xff682c,2,9);light.position.set(x,1,z);scene.add(light);let flame=mesh(coneGeo,new THREE.MeshBasicMaterial({color:0xff6a27}),x,.55,z,.34,1,.34,false);fires.push({light,flame})}
// Friendly fallen soldier props as low-detail battlefield dressing
function corpse(x,z){let g=new THREE.Group();let body=new THREE.Mesh(boxGeo,mats.canvas);body.scale.set(.55,.32,1.4);body.position.y=.35;body.rotation.x=.15;g.add(body);let head=new THREE.Mesh(sphereGeo,mats.trunk);head.scale.set(.34,.3,.34);head.position.set(0,.42,-.8);g.add(head);let helmet=new THREE.Mesh(sphereGeo,mats.metal);helmet.scale.set(.4,.2,.4);helmet.position.set(0,.59,-.8);g.add(helmet);let blood=new THREE.Mesh(new THREE.CircleGeometry(.65,12),mats.blood);blood.rotation.x=-Math.PI/2;blood.position.y=.01;g.add(blood);g.position.set(x,0,z);g.rotation.y=Math.random()*6;scene.add(g)}for(let i=0;i<10;i++)corpse((Math.random()-.5)*45,(Math.random()-.5)*42);
// Procedural soldier arms and weapon viewmodel
const viewmodel=new THREE.Group();camera.add(viewmodel);scene.add(camera);
const sleeveMat=mat(0x4b5143),skinMat=mat(0x8e7962),gunMat=mat(0x292d2a,.45,.65),woodMat=mat(0x54402e,.72);
function arm(x,y,z,rot=0){let a=new THREE.Mesh(cylGeo,sleeveMat);a.scale.set(.12,.43,.13);a.position.set(x,y,z);a.rotation.z=rot;viewmodel.add(a);let hand=new THREE.Mesh(sphereGeo,skinMat);hand.scale.set(.11,.12,.13);hand.position.set(x,y-.22,z);viewmodel.add(hand)}
arm(-.36,-.35,-.67,-.18);arm(.34,-.34,-.78,.22);
const gun=new THREE.Group();viewmodel.add(gun);function vg(geo,m,x,y,z,sx,sy,sz){let o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);gun.add(o);return o}
vg(boxGeo,woodMat,0,-.18,-.78,.16,.17,.72);vg(boxGeo,gunMat,0,-.08,-1.07,.13,.13,.55);vg(cylGeo,gunMat,0,-.06,-1.55,.035,.68,.035).rotation.x=Math.PI/2;vg(boxGeo,gunMat,0,-.24,-.93,.105,.2,.14);vg(boxGeo,woodMat,0,-.12,-.54,.12,.3,.15);
const weaponDefs=[{name:'KAR98K',type:'FUZIL DE FERROLHO',mag:5,reserve:30,damage:86,rate:.82,reload:2.15,spread:.009,auto:false},{name:'LUGER P08',type:'PISTOLA SEMIAUTOMÁTICA',mag:8,reserve:40,damage:43,rate:.25,reload:1.55,spread:.024,auto:false},{name:'MP40',type:'SUBMETRALHADORA',mag:32,reserve:96,damage:29,rate:.095,reload:2.1,spread:.045,auto:true,locked:true},{name:'MG42',type:'METRALHADORA',mag:60,reserve:120,damage:24,rate:.075,reload:3.2,spread:.065,auto:true,locked:true},{name:'MINIGUN',type:'ARMA EXPERIMENTAL',mag:180,reserve:180,damage:18,rate:.045,reload:4,spread:.09,auto:true,locked:true}];let weapons=weaponDefs.map(w=>({...w,ammo:w.mag}));let equipped=0;
function setWeapon(id){if(!weapons[id]||weapons[id].locked)return;equipped=id;const w=weapons[id];$('#weaponName').textContent=w.name;$('#weaponType').textContent=w.type;$('#weaponSlot').textContent=`0${id+1} / 0${weapons.filter(a=>!a.locked).length}`;updateAmmo();viewmodel.position.set(0,0,0);viewmodel.rotation.set(0,0,0);if(id===1){gun.position.y=-.09;gun.scale.set(.75,.72,.72)}else{gun.position.y=0;gun.scale.set(1,1,1)}}
function updateAmmo(){let w=weapons[equipped];$('#ammo').innerHTML=`${w.ammo} <small>/ ${w.reserve}</small>`;$('#ammoState').textContent=w.ammo<=Math.max(2,Math.round(w.mag*.2))?'MUNIÇÃO BAIXA':'PRONTO';$('#ammoState').style.color=w.ammo<=2?'#dd795e':''}
setWeapon(0);

// Infected archetypes: compact articulated meshes, each with distinct silhouette and movement
const infectedDefs={common:{hp:92,speed:1.55,damage:9,reach:1.35,scale:1,color:0x77705e,attack:1.2},runner:{hp:65,speed:3.7,damage:8,reach:1.2,scale:.94,color:0x5c6457,attack:.9},brute:{hp:340,speed:.92,damage:23,reach:1.8,scale:1.55,color:0x574b41,attack:1.7},spitter:{hp:100,speed:1.2,damage:13,reach:13,scale:1.05,color:0x665d54,attack:3.5},abomination:{hp:1250,speed:1.05,damage:34,reach:2.4,scale:2.35,color:0x51433d,attack:1.4}};
const enemies=[];let kills=0;const hitMeshes=new Map();
function makeEnemy(type,x,z){let d=infectedDefs[type],g=new THREE.Group(),skin=mat(d.color),dark=mat(0x302d28),wound=mat(0x6d3329);function part(geo,m,px,py,pz,sx,sy,sz){let o=new THREE.Mesh(geo,m);o.position.set(px,py,pz);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;g.add(o);return o}let s=d.scale;
let torso=part(boxGeo,skin,0,.98*s,0,.62*s,.95*s,.35*s);torso.rotation.x=(Math.random()-.5)*.2;let head=part(sphereGeo,skin,0,1.69*s,-.02*s,.32*s,.37*s,.33*s);let jaw=part(boxGeo,dark,0,1.48*s,-.24*s,.24*s,.13*s,.18*s);let armL=part(cylGeo,skin,-.44*s,1.02*s,-.04,.18*s,.8*s,.2*s),armR=part(cylGeo,skin,.44*s,1.02*s,.03,.18*s,.8*s,.2*s);armL.rotation.z=-.42;armR.rotation.z=.42;let legL=part(cylGeo,dark,-.2*s,.4*s,0,.22*s,.8*s,.22*s),legR=part(cylGeo,dark,.2*s,.4*s,0,.22*s,.8*s,.22*s);let eyes=[];if(type==='spitter'){part(sphereGeo,wound,0,1.92*s,-.02*s,.35*s,.2*s,.32*s);for(let xx of [-.13,.13])eyes.push(part(sphereGeo,mat(0xb7aa75),xx*s,1.71*s,-.3*s,.05*s,.045*s,.025*s))}if(type==='brute'||type==='abomination'){part(boxGeo,dark,0,1.3*s,.24*s,.77*s,.16*s,.2*s);part(sphereGeo,wound,-.22*s,1.22*s,-.2*s,.16*s,.22*s,.08*s)}if(type==='runner'){torso.rotation.x=-.3;head.position.y=1.58*s;armL.rotation.z=-.7;armR.rotation.z=.7}g.position.set(x,0,z);scene.add(g);let enemy={type,g,hp:d.hp,max:d.hp,speed:d.speed,damage:d.damage,reach:d.reach,attack:d.attack,clock:Math.random(),parts:{torso,head,armL,armR,legL,legR,jaw},alive:true,stun:0,targetX:x,targetZ:z,anim:Math.random()*10};enemies.push(enemy);for(let c of g.children)if(c.isMesh)hitMeshes.set(c,enemy);return enemy}
function removeEnemy(e){if(!e.alive)return;e.alive=false;kills++;$('#killfeed').insertAdjacentHTML('afterbegin',`<div>✕ &nbsp;INFECTADO ELIMINADO</div>`);for(let c of e.g.children)hitMeshes.delete(c);let geom=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(e.g.position.x,.35,e.g.position.z),new THREE.Vector3(e.g.position.x+Math.random()-.5,.2,e.g.position.z+Math.random()-.5)]);let line=new THREE.Line(geom,new THREE.LineBasicMaterial({color:0x572a20,transparent:true,opacity:.8}));scene.add(line);setTimeout(()=>{scene.remove(line);scene.remove(e.g)},2200)}
function hurtEnemy(e,damage){if(!e?.alive)return;e.hp-=damage;e.stun=.16;$('#hitmarker').classList.remove('show');void $('#hitmarker').offsetWidth;$('#hitmarker').classList.add('show');if(e.hp<=0)removeEnemy(e)}
const player={pos:new THREE.Vector3(0,1.7,8),yaw:0,pitch:0,hp:100,stamina:100,alive:true,locked:false,move:new THREE.Vector2(),crouch:false};camera.position.copy(player.pos);
let elapsed=0, extraction=0,started=false,paused=false,gameOver=false,spawnClock=0,supplyClock=0,lastShot=0,reloadTimer=0,shots=0,hits=0,ammoUsed=0,damageTaken=0,supplyCount=0,foundWeapons=0,grenades=2,autoFire=false,aiming=false;const clock=new THREE.Clock();
const audio={ctx:null,master:null,init(){if(this.ctx)return;this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=.22;this.master.connect(this.ctx.destination)},tone(freq,dur,type='sine',vol=.15,slide=0){if(!this.ctx)return;let o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,this.ctx.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),this.ctx.currentTime+dur);g.gain.setValueAtTime(vol,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+dur);o.connect(g);g.connect(this.master);o.start();o.stop(this.ctx.currentTime+dur)},noise(dur=.15,vol=.14,filter=1200){if(!this.ctx)return;let n=this.ctx.createBufferSource(),b=this.ctx.createBuffer(1,this.ctx.sampleRate*dur,this.ctx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;n.buffer=b;let f=this.ctx.createBiquadFilter();f.type='lowpass';f.frequency.value=filter;let g=this.ctx.createGain();g.gain.setValueAtTime(vol,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+dur);n.connect(f);f.connect(g);g.connect(this.master);n.start()},gun(){let w=weapons[equipped];this.noise(.17,equipped===4?.36:.28,equipped===0?1000:2400);this.tone(equipped===0?90:125,.19,'sawtooth',.16,-70);this.tone(45,.11,'sine',.28,-30)},hit(){this.noise(.08,.14,700)},hurt(){this.tone(90,.32,'sawtooth',.22,-48)},thunder(){this.noise(1,.12,300)},pickup(){this.tone(510,.11,'sine',.12,160);this.tone(760,.16,'sine',.1,120)}};
function announce(text,seconds=3){let n=$('#notice');n.textContent=text;n.classList.add('show');clearTimeout(n._t);n._t=setTimeout(()=>n.classList.remove('show'),seconds*1000)}
function speak(text){try{let u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=.83;u.pitch=.75;speechSynthesis.speak(u)}catch{}}
// Supply crate physics, parachute and a glowing field marker
const supplies=[];
function makeSupply(){let x=(Math.random()-.5)*48,z=(Math.random()-.5)*50;let g=new THREE.Group();let crate=new THREE.Mesh(boxGeo,mat(0x776b4d));crate.scale.set(.9,.72,.85);crate.position.y=-.6;crate.castShadow=true;g.add(crate);for(let a of [-.34,.34]){let band=new THREE.Mesh(boxGeo,mat(0x393d32));band.scale.set(.08,.75,.9);band.position.set(a,-.6,0);g.add(band)}let canopy=new THREE.Mesh(new THREE.SphereGeometry(1,12,8,0,Math.PI*2,0,Math.PI/2),new THREE.MeshStandardMaterial({color:0xaaa183,side:THREE.DoubleSide,roughness:1}));canopy.scale.set(1.7,.58,1.7);canopy.position.y=2.1;g.add(canopy);for(let a of [-.55,.55])for(let b of [-.55,.55]){let line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a,1.9,b),new THREE.Vector3(a*.6,-.2,b*.6)]),new THREE.LineBasicMaterial({color:0xc2b99b}));g.add(line)}g.position.set(x,25,z);scene.add(g);supplies.push({g,x,z,y:25,landed:false,open:false,vel:0});announce('SUPRIMENTOS DETECTADOS',4);audio.tone(420,.28,'sine',.14,180)}
