scene.add(new THREE.HemisphereLight(0xc3ccd0,0x3c4033,1.5));const sun=new THREE.DirectionalLight(0xffddb1,2);sun.position.set(-35,52,22);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mat=(c,r=.9,m=0)=>new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:m});
const M={ground:mat(0x4b4d3e),mud:mat(0x38382f),grass:mat(0x535744),stone:mat(0x77756b),dark:mat(0x45473f),wood:mat(0x493b2c),burn:mat(0x262724),roof:mat(0x3a3933),brick:mat(0x745f4e),metal:mat(0x303632,.62,.48),rust:mat(0x5e4433,.7,.25),leaf:mat(0x29372b),leaf2:mat(0x3d4833),trunk:mat(0x443b2d),canvas:mat(0x696b52)};
const box=new THREE.BoxGeometry(1,1,1),sphere=new THREE.SphereGeometry(1,10,8),cyl=new THREE.CylinderGeometry(1,1,1,8),cone=new THREE.ConeGeometry(1,1,6);
function add(geo,material,x,y,z,sx=1,sy=1,sz=1,cast=true){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=cast;o.receiveShadow=true;scene.add(o);return o}function block(x,y,z,sx,sy,sz,m=M.stone){return add(box,m,x,y,z,sx,sy,sz)}
const colliders=[];function collider(x,z,w,d){colliders.push({x,z,w,d})}
const floor=add(new THREE.PlaneGeometry(180,180),M.ground,0,-.18,0,1,1,1,false);floor.rotation.x=-Math.PI/2;
for(let i=0;i<220;i++){let x=(Math.random()-.5)*118,z=(Math.random()-.5)*118,r=.4+Math.random()*1.5,o=add(sphere,Math.random()<.5?M.mud:M.grass,x,-.1,z,r,.07,r*.7,false);o.rotation.y=Math.random()*3}
const road=add(new THREE.PlaneGeometry(5,95),M.mud,3,.005,0,1,1,1,false);road.rotation.x=-Math.PI/2;road.rotation.z=.12;
for(let i=0;i<14;i++){let x=(Math.random()-.5)*42,z=(Math.random()-.5)*48,r=.7+Math.random()*1.8,o=add(new THREE.CircleGeometry(r,14),M.mud,x,.006,z,1,1,.62,false);o.rotation.x=-Math.PI/2}
function house(x,z,w,d,h=4,ruin=false){let m=Math.random()<.5?M.brick:M.stone;block(x-w/2,h/2,z,w,h,d*.13,m);block(x+w/2,h/2,z,w,h,d*.13,m);block(x,h/2,z-d/2,w*.13,h,d,m);if(!ruin){block(x,h+.1,z,w+1,.32,d+1,M.roof);for(let xx of [-w*.23,w*.23])block(x+xx,1.2,z-d/2-.08,.8,1.5,.18,M.dark)}else{block(x-w*.25,h*.83,z,w*.5,.35,d,M.roof);block(x+w*.42,1.5,z+d*.1,.38,2,.4,M.burn);for(let j=0;j<5;j++)block(x+(Math.random()-.5)*w,.3,z+(Math.random()-.5)*d,.5,.3,.5,M.brick)}collider(x,z,w,d)}
house(-16,-11,11,9,5,true);house(-27,-3,8,7,4,true);house(18,-12,10,8,4.5,true);house(27,-3,9,7,4,false);house(-18,10,9,7,4,false);house(17,12,10,8,4,true);
// Bombed church, trenches, bunker, observation post
block(-1,2,-23,18,4,1,M.stone);block(-9,3,-23,2,6,2,M.stone);block(-9,7,-23,4,.55,4,M.roof);block(-9,9,-23,1,4,1,M.dark);add(cone,M.roof,-9,12,-23,1.35,3.8,1.35);block(-1,3,-29,1,6,11,M.dark);block(5,2,-23,2,4,1,M.brick);collider(-4,-24,18,12);
function trench(x,z,len,rot=0){let g=new THREE.Group();for(let i of [-1,1]){let b=new THREE.Mesh(box,M.mud);b.position.set(i*1.25,.25,0);b.scale.set(.55,.65,len);g.add(b);let berm=new THREE.Mesh(box,M.grass);berm.position.set(i*1.75,.48,0);berm.scale.set(.5,.8,len);g.add(berm)}let f=new THREE.Mesh(box,M.wood);f.position.y=-.12;f.scale.set(2,.12,len);g.add(f);g.position.set(x,0,z);g.rotation.y=rot;scene.add(g)}trench(-4,7,17);trench(-10,14,15,Math.PI/2);trench(4,17,17,.14);trench(9,8,18,Math.PI/2);
block(0,.6,25,11,2.3,7,M.dark);block(0,1.8,21.4,5,1.1,.5,M.metal);collider(0,25,11,7);for(let x of [31,35]){block(x,2,19,.25,4,.25,M.wood);block(x+2,2,19,.25,4,.25,M.wood);block(x+1,4,19,2.5,.3,.3,M.wood)}
for(let i=0;i<82;i++){let x=(Math.random()-.5)*80,z=-42-Math.random()*20;if(Math.abs(x)<20)continue;let h=5+Math.random()*7;add(cyl,M.trunk,x,h*.32,z,.32,h*.65,.32);for(let k=0;k<3;k++)add(cone,k%2?M.leaf:M.leaf2,x,h*.43+k*h*.2,z,2.3-k*.46,h*.42,2.3-k*.46)}
for(let i=0;i<22;i++){let x=(Math.random()-.5)*88,z=35+Math.random()*17,h=5+Math.random()*6;add(cyl,M.trunk,x,h*.3,z,.3,h*.6,.3);for(let k=0;k<3;k++)add(cone,M.leaf,x,h*.38+k*h*.21,z,2-k*.4,h*.43,2-k*.4)}
function tank(x,z,rot=0){let g=new THREE.Group();const p=(geo,m,a,b,c,sx,sy,sz)=>{let o=new THREE.Mesh(geo,m);o.position.set(a,b,c);o.scale.set(sx,sy,sz);g.add(o)};p(box,M.burn,0,1,0,4.6,1.35,2.7);p(box,M.rust,0,1.9,0,2.5,.9,2.1);p(cyl,M.metal,0,2.2,-1.7,.28,4,.28);for(let s of [-1,1]){p(box,M.metal,s*2.35,.8,0,.35,1.3,2.8);for(let j=0;j<4;j++)p(cyl,M.burn,s*2.55,.65,-1+j*.68,.48,.22,.48)}g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);collider(x,z,5,3.5)}tank(-24,20,.4);tank(23,5,-.5);
for(let i=0;i<55;i++){let x=(Math.random()-.5)*54,z=(Math.random()-.5)*54;if(Math.abs(x)<7&&Math.abs(z)<7)continue;let b=add(box,i%3?M.wood:M.stone,x,.3,z,.65+Math.random()*.7,.5,.5+Math.random()*.7);b.rotation.y=Math.random()*3}
const smoke=[],smokeMat=new THREE.MeshBasicMaterial({color:0x3a3b37,transparent:true,opacity:.17,depthWrite:false});for(let i=0;i<12;i++){let g=new THREE.Group();for(let j=0;j<5;j++){let p=new THREE.Mesh(sphere,smokeMat);p.position.set((Math.random()-.5)*1.5,j*.8,(Math.random()-.5)*1.2);p.scale.set(1.7,1.5,1.4);g.add(p)}g.position.set((Math.random()-.5)*48,1,-20+Math.random()*44);scene.add(g);smoke.push(g)}
const rainN=850,rainGeo=new THREE.BufferGeometry(),rainPos=new Float32Array(rainN*3);for(let i=0;i<rainN;i++){rainPos[i*3]=(Math.random()-.5)*95;rainPos[i*3+1]=Math.random()*30;rainPos[i*3+2]=(Math.random()-.5)*95}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0xaeb8b7,size:.055,transparent:true,opacity:.4}));scene.add(rain);
const fires=[];for(const [x,z] of [[-18,-10],[18,-12],[-25,19]]){let l=new THREE.PointLight(0xff682c,2,9);l.position.set(x,1,z);scene.add(l);let f=add(cone,new THREE.MeshBasicMaterial({color:0xff6a27}),x,.55,z,.34,1,.34,false);fires.push({l,f})}
// Player first-person view model
const view=new THREE.Group();camera.add(view);scene.add(camera);const sleeve=mat(0x4b5143),skin=mat(0x8e7962),gunMetal=mat(0x292d2a,.45,.65),gunWood=mat(0x54402e,.72);
function arm(x,y,z,r){let a=new THREE.Mesh(cyl,sleeve);a.scale.set(.12,.43,.13);a.position.set(x,y,z);a.rotation.z=r;view.add(a);let h=new THREE.Mesh(sphere,skin);h.scale.set(.11,.12,.13);h.position.set(x,y-.22,z);view.add(h)}arm(-.36,-.35,-.67,-.18);arm(.34,-.34,-.78,.22);
const gun=new THREE.Group();view.add(gun);function vg(g,m,x,y,z,sx,sy,sz){let o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);gun.add(o)}vg(box,gunWood,0,-.18,-.78,.16,.17,.72);vg(box,gunMetal,0,-.08,-1.07,.13,.13,.55);vg(cyl,gunMetal,0,-.06,-1.55,.035,.68,.035).rotation.x=Math.PI/2;vg(box,gunMetal,0,-.24,-.93,.105,.2,.14);vg(box,gunWood,0,-.12,-.54,.12,.3,.15);

