// Combat, survival loop, and interface
const weapons=[
 {name:'KAR98K',type:'FUZIL DE FERROLHO',mag:5,reserve:35,damage:68,rate:.82,spread:.006,reload:1.55,auto:false},
 {name:'MP40',type:'SUBMETRALHADORA',mag:32,reserve:160,damage:23,rate:.105,spread:.045,reload:1.65,auto:true},
 {name:'STG 44',type:'FUZIL DE ASSALTO',mag:30,reserve:150,damage:31,rate:.13,spread:.025,reload:1.75,auto:true},
 {name:'P08 LUGER',type:'PISTOLA SEMIAUTOMÁTICA',mag:8,reserve:48,damage:35,rate:.28,spread:.018,reload:1.2,auto:false}
];
let weaponIndex=0,ammo=weapons.map(w=>w.mag),reserve=weapons.map(w=>w.reserve),health=100,stamina=100,timeLeft=300,kills=0,shots=0,started=false,paused=false,ended=false,cinematic=0,mouseDown=false,aiming=false,reloading=0,shootWait=0,damageFlash=0,noticeTime=0,elapsed=0,walkPhase=0,grenades=2;
const keys={},enemies=[],pickups=[],tracers=[],effects=[];const raycaster=new THREE.Raycaster(),clock=new THREE.Clock(),forward=new THREE.Vector3(),right=new THREE.Vector3(),move=new THREE.Vector3(),enemyMat=mat(0x45473c),enemyCloth=mat(0x555044),enemySkin=mat(0x987e65),enemyMetal=mat(0x353934,.58,.55);
camera.position.set(0,1.65,1.5);let yaw=0,pitch=0;camera.rotation.order='YXZ';
function audioInit(){if(!audio.ctx){try{audio.ctx=new (window.AudioContext||window.webkitAudioContext)()}catch{}}if(audio.ctx?.state==='suspended')audio.ctx.resume()}
const audio={ctx:null,play(freq=150,duration=.08,kind='square',volume=.035){if(!this.ctx)return;try{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=kind;o.frequency.setValueAtTime(freq,this.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.45),this.ctx.currentTime+duration);g.gain.setValueAtTime(volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}catch{}}};
function announce(text,seconds=2.5){$('#notice').textContent=text;$('#notice').classList.add('visible');noticeTime=seconds}
function updateWeaponHud(){let w=weapons[weaponIndex];$('#weaponName').textContent=w.name;$('#weaponType').textContent=w.type;$('#weaponSlot').textContent=`0${weaponIndex+1} / 04`;$('#ammo').innerHTML=`${ammo[weaponIndex]} <small>/ ${reserve[weaponIndex]}</small>`;$('#ammoState').textContent=reloading?'RECARREGANDO':ammo[weaponIndex]===0?'SEM MUNIÇÃO':'PRONTO';$('#ammoPips').innerHTML=Array.from({length:Math.min(w.mag,12)},(_,i)=>`<i class="${i<ammo[weaponIndex]?'loaded':''}"></i>`).join('')}
function setWeapon(n){if(n<0||n>=weapons.length||weaponIndex===n||reloading)return;weaponIndex=n;gun.rotation.set(0,0,0);announce(weapons[n].name,1.1);updateWeaponHud()}
function startReload(){let w=weapons[weaponIndex];if(reloading||ammo[weaponIndex]>=w.mag||reserve[weaponIndex]<=0)return;reloading=w.reload;audio.play(360,.12,'triangle',.02);announce('RECARREGANDO…',w.reload);updateWeaponHud()}
function finishReload(){let w=weapons[weaponIndex],n=Math.min(w.mag-ammo[weaponIndex],reserve[weaponIndex]);ammo[weaponIndex]+=n;reserve[weaponIndex]-=n;reloading=0;audio.play(520,.08,'triangle',.025);updateWeaponHud()}
function makeEnemy(x,z){const g=new THREE.Group();const torso=new THREE.Mesh(box,enemyCloth);torso.position.y=1.02;torso.scale.set(.62,.86,.38);g.add(torso);const head=new THREE.Mesh(sphere,enemySkin);head.position.y=1.67;head.scale.set(.23,.27,.23);g.add(head);const helmet=new THREE.Mesh(sphere,enemyMat);helmet.position.y=1.84;helmet.scale.set(.28,.14,.29);g.add(helmet);for(const s of [-1,1]){const limb=new THREE.Mesh(box,enemyCloth);limb.position.set(s*.39,1.07,0);limb.scale.set(.2,.72,.24);limb.rotation.z=s*.1;g.add(limb);const leg=new THREE.Mesh(box,enemyMat);leg.position.set(s*.18,.4,0);leg.scale.set(.22,.75,.26);g.add(leg)}const rifle=new THREE.Mesh(box,enemyMetal);rifle.position.set(.13,1.1,-.38);rifle.scale.set(.13,.12,.8);g.add(rifle);g.position.set(x,0,z);scene.add(g);let e={g,hp:100,attack:1+Math.random()*1.8,mesh:g.children.slice(0,3),dead:false,speed:1.05+Math.random()*.42,phase:Math.random()*7};enemies.push(e);return e}
function spawnEnemy(){let a=Math.random()*Math.PI*2,r=25+Math.random()*14,x=Math.sin(a)*r,z=Math.cos(a)*r;if(Math.abs(x)<4&&z<0)z-=8;makeEnemy(x,z)}
for(let i=0;i<5;i++)spawnEnemy();
function makePickup(x,z,type='ammo'){let g=new THREE.Group(),color=type==='med'?0x777d5d:type==='grenade'?0x526044:0x9b8052;let crate=new THREE.Mesh(box,mat(color));crate.scale.set(.68,.42,.55);crate.position.y=.24;g.add(crate);let mark=new THREE.Mesh(box,mat(0xd0c8a9));mark.scale.set(.34,.05,.06);mark.position.set(0,.47,0);g.add(mark);g.position.set(x,.03,z);scene.add(g);pickups.push({g,type})}
for(const p of [[-5,10],[-18,4],[12,-5],[4,21],[25,8],[-29,11]])makePickup(...p,Math.random()<.24?'med':'ammo');makePickup(7,14,'grenade');
function nearObstacle(x,z){for(const c of colliders)if(Math.abs(x-c.x)<c.w*.52+.38&&Math.abs(z-c.z)<c.d*.52+.38)return true;return false}
function movePlayer(dx,dz){let x=camera.position.x+dx,z=camera.position.z+dz;if(!nearObstacle(x,camera.position.z))camera.position.x=x;if(!nearObstacle(camera.position.x,z))camera.position.z=z;camera.position.x=THREE.MathUtils.clamp(camera.position.x,-48,48);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-49,48)}
function aimRay(){camera.updateMatrixWorld();raycaster.setFromCamera(new THREE.Vector2(0,0),camera);raycaster.far=100;return raycaster}
function hitEnemy(e,dmg){e.hp-=dmg;$('#hitmarker').classList.add('on');setTimeout(()=>$('#hitmarker').classList.remove('on'),90);if(e.hp<=0&&!e.dead){e.dead=true;kills++;$('#killfeed').innerHTML=`<div>✕ <b>HOSTIL NEUTRALIZADO</b><small>+ 100 XP</small></div>`+$('#killfeed').innerHTML;setTimeout(()=>{if($('#killfeed').firstElementChild)$('#killfeed').firstElementChild.remove()},3500);scene.remove(e.g);if(Math.random()<.42)makePickup(e.g.position.x,e.g.position.z,'ammo');audio.play(90,.18,'sawtooth',.04)}}
function fire(){if(!started||paused||ended||cinematic>0||reloading||shootWait>0)return;if(ammo[weaponIndex]<=0){audio.play(100,.07,'square',.018);startReload();return}let w=weapons[weaponIndex];ammo[weaponIndex]--;shots++;shootWait=w.rate;updateWeaponHud();gun.position.z=.13;gun.rotation.x=-.045;audio.play(weaponIndex===0?105:weaponIndex===1?145:weaponIndex===2?125:210,weaponIndex===0?.19:.08,weaponIndex===0?'sawtooth':'square',weaponIndex===0?.085:.045);let r=aimRay();let meshes=[];for(const e of enemies)if(!e.dead)meshes.push(...e.mesh);const hits=r.intersectObjects(meshes,false);if(hits.length){let e=enemies.find(q=>q.mesh.includes(hits[0].object));if(e)hitEnemy(e,w.damage*(hits[0].object===e.mesh[1]?1.7:1))}else{let dir=new THREE.Vector3();camera.getWorldDirection(dir);let start=camera.position.clone().add(dir.multiplyScalar(.5));let end=start.clone().add(dir.multiplyScalar(24));const geom=new THREE.BufferGeometry().setFromPoints([start,end]);let line=new THREE.Line(geom,new THREE.LineBasicMaterial({color:0xffd18a,transparent:true,opacity:.8}));scene.add(line);tracers.push({o:line,t:.055})}}
function throwGrenade(){if(grenades<=0||!started||paused||cinematic>0)return;grenades--;announce(`GRANADA LANÇADA · ${grenades} RESTANTE(S)`,1.5);audio.play(260,.16,'triangle',.04);let dir=new THREE.Vector3();camera.getWorldDirection(dir);let target=camera.position.clone().add(dir.multiplyScalar(12));let flare=add(sphere,mat(0x6b7257),target.x,.4,target.z,.22,.22,.22);setTimeout(()=>{scene.remove(flare);audio.play(65,.65,'sawtooth',.1);let boom=new THREE.PointLight(0xff9a43,10,14);boom.position.set(target.x,1,target.z);scene.add(boom);setTimeout(()=>scene.remove(boom),180);for(const e of enemies)if(!e.dead&&e.g.position.distanceTo(target)<8)hitEnemy(e,130);let ring=add(new THREE.Mesh(new THREE.TorusGeometry(1,.09,6,24),new THREE.MeshBasicMaterial({color:0xffa048,transparent:true,opacity:.8})),undefined,target.x,.1,target.z);ring.rotation.x=Math.PI/2;effects.push({o:ring,t:.8})},850)}
function takeDamage(amount){if(ended)return;health=Math.max(0,health-amount);damageFlash=.35;$('#hurt').classList.add('active');$('#healthNum').textContent=Math.ceil(health);$('#healthBar').style.width=health+'%';$('#statusText').textContent=health<30?'CRÍTICO':health<60?'FERIDO':'ESTÁVEL';$('#statusText').style.color=health<30?'#dc6651':'';audio.play(72,.12,'sawtooth',.04);if(health<=0)endGame(false)}
function interact(){let p=pickups.find(q=>q.g.position.distanceTo(camera.position)<2.6);if(!p)return;if(p.type==='med'){health=Math.min(100,health+35);$('#healthNum').textContent=Math.ceil(health);$('#healthBar').style.width=health+'%';announce('KIT MÉDICO · +35 CONDIÇÃO',2)}else if(p.type==='grenade'){grenades++;announce(`GRANADA RECOLHIDA · ${grenades} DISPONÍVEIS`,2)}else{for(let i=0;i<reserve.length;i++)reserve[i]+=i===0?8:i===3?12:30;announce('MUNIÇÃO REABASTECIDA',2);updateWeaponHud()}scene.remove(p.g);pickups.splice(pickups.indexOf(p),1);audio.play(620,.12,'triangle',.04)}
function endGame(won){if(ended)return;ended=true;paused=false;document.exitPointerLock?.();$('#pauseScreen').classList.add('hidden');$('#endScreen').classList.remove('hidden');$('#endOverline').textContent=won?'EXTRAÇÃO CONFIRMADA':'RELATÓRIO FINAL';$('#endTitle').innerHTML=won?'MISSÃO<br>CONCLUÍDA':'OPERAÇÃO<br>FRACASSADA';$('#endSub').textContent=won?'Você resistiu até a chegada da extração.':'A posição foi perdida. O rádio permanece em silêncio.';$('#stats').innerHTML=`<div><small>HOSTIS NEUTRALIZADOS</small><b>${kills}</b></div><div><small>PRECISÃO</small><b>${shots?Math.round(kills/shots*100):0}%</b></div><div><small>TEMPO RESISTIDO</small><b>${Math.floor((300-timeLeft)/60)}:${String(Math.floor((300-timeLeft)%60)).padStart(2,'0')}</b></div>`}
function beginOperation(){if(started)return;audioInit();started=true;cinematic=4;$('#intro').classList.add('hidden');$('#loading').classList.add('hidden');$('#hud').classList.remove('hidden');$('#objective').textContent='SOBREVIVA POR 5 MINUTOS';announce('POSIÇÃO COMPROMETIDA · INIMIGOS SE APROXIMANDO',4);renderer.domElement.requestPointerLock?.();updateWeaponHud()}
$('#startButton').addEventListener('click',beginOperation);$('#resumeButton').addEventListener('click',()=>{paused=false;$('#pauseScreen').classList.add('hidden');audioInit();renderer.domElement.requestPointerLock?.()});$('#restartButton').addEventListener('click',()=>location.reload());
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'&&started&&!ended){if(paused){paused=false;$('#pauseScreen').classList.add('hidden');renderer.domElement.requestPointerLock?.()}else{paused=true;$('#pauseScreen').classList.remove('hidden')}}if(!started||ended)return;if(e.code==='KeyR')startReload();if(e.code==='KeyE')interact();if(e.code==='KeyG')throwGrenade();if(/^Digit[1-4]$/.test(e.code))setWeapon(Number(e.code.slice(-1))-1);if(e.code==='Space')fire()});window.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!paused){yaw-=e.movementX*.0022;pitch-=e.movementY*.0022;pitch=THREE.MathUtils.clamp(pitch,-1.35,1.35);camera.rotation.set(pitch,yaw,0,'YXZ')}});
document.addEventListener('pointerlockchange',()=>{if(started&&!ended&&!document.pointerLockElement&&!paused&&cinematic<=0){paused=true;$('#pauseScreen').classList.remove('hidden')}});
renderer.domElement.addEventListener('click',()=>{if(started&&!paused&&!ended){if(!document.pointerLockElement)renderer.domElement.requestPointerLock?.();else if(!weapons[weaponIndex].auto)fire()}});window.addEventListener('mousedown',e=>{if(e.button===0){mouseDown=true;if(started&&!paused&&!ended&&weapons[weaponIndex].auto)fire()}});window.addEventListener('mouseup',()=>mouseDown=false);
$('#touchFire').addEventListener('touchstart',e=>{e.preventDefault();mouseDown=true;fire()},{passive:false});$('#touchFire').addEventListener('touchend',()=>mouseDown=false);$('#touchReload').addEventListener('click',startReload);$('#touchAim').addEventListener('touchstart',e=>{e.preventDefault();aiming=true;camera.fov=52;camera.updateProjectionMatrix()},{passive:false});$('#touchAim').addEventListener('touchend',()=>{aiming=false;camera.fov=73;camera.updateProjectionMatrix()});
let stickPointer=null;$('#moveStick').addEventListener('pointerdown',e=>{stickPointer=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);updateStick(e)});$('#moveStick').addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)updateStick(e)});$('#moveStick').addEventListener('pointerup',()=>{stickPointer=null;touchVec={x:0,y:0};$('#moveStick span').style.transform='translate(0,0)'});let touchVec={x:0,y:0};function updateStick(e){let r=$('#moveStick').getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),d=Math.hypot(x,y),m=Math.min(1,d/42);touchVec={x:d?x/d*m:0,y:d?y/d*m:0};$('#moveStick span').style.transform=`translate(${touchVec.x*32}px,${touchVec.y*32}px)`}
function update(dt){elapsed+=dt;if(!started||paused||ended)return;if(cinematic>0){cinematic-=dt;yaw+=dt*.04;camera.rotation.set(.015,yaw,0,'YXZ')}if(timeLeft>0){timeLeft=Math.max(0,timeLeft-dt);let mins=Math.floor(timeLeft/60),secs=Math.floor(timeLeft%60);$('#timer').textContent=`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;if(timeLeft===0){$('#objective').textContent='EXTRAÇÃO EM ANDAMENTO';announce('SINALIZADOR ATIVO · EXTRAÇÃO CONFIRMADA',5);setTimeout(()=>endGame(true),4000)}}if(noticeTime>0&&(noticeTime-=dt)<=0)$('#notice').classList.remove('visible');if(damageFlash>0&&(damageFlash-=dt)<=0)$('#hurt').classList.remove('active');if(shootWait>0)shootWait-=dt;if(reloading>0&&(reloading-=dt)<=0)finishReload();gun.position.z=THREE.MathUtils.lerp(gun.position.z,0,Math.min(1,dt*12));gun.rotation.x=THREE.MathUtils.lerp(gun.rotation.x,0,Math.min(1,dt*10));
