// Combat, survival loop, and interface
const weapons=[
 {name:'KAR98K',type:'FUZIL DE FERROLHO',mag:5,reserve:35,damage:68,rate:.82,spread:.006,reload:1.55,auto:false},
 {name:'MP40',type:'SUBMETRALHADORA',mag:32,reserve:160,damage:23,rate:.105,spread:.045,reload:1.65,auto:true},
 {name:'STG 44',type:'FUZIL DE ASSALTO',mag:30,reserve:150,damage:31,rate:.13,spread:.025,reload:1.75,auto:true},
 {name:'P08 LUGER',type:'PISTOLA SEMIAUTOMÁTICA',mag:8,reserve:48,damage:35,rate:.28,spread:.018,reload:1.2,auto:false}
];
let weaponIndex=0,ammo=weapons.map(w=>w.mag),reserve=weapons.map(w=>w.reserve),health=100,stamina=100,timeLeft=300,kills=0,shots=0,started=false,paused=false,ended=false,cinematic=0,mouseDown=false,aiming=false,reloading=0,shootWait=0,damageFlash=0,noticeTime=0,elapsed=0,walkPhase=0,grenades=2;
const keys={},enemies=[],pickups=[],tracers=[],effects=[];const raycaster=new THREE.Raycaster(),clock=new THREE.Clock(),forward=new THREE.Vector3(),right=new THREE.Vector3(),move=new THREE.Vector3(),enemyMat=mat(0x45473c),enemyCloth=mat(0x555044),enemySkin=mat(0x987e65),enemyMetal=mat(0x353934,.58,.55);
camera.position.set(0,1.65,1.5);let yaw=0,pitch=0;camera.rotation.order='YXZ';
function audioInit(){if(!audio.ctx){try{audio.ctx=new (window.AudioContext||window.webkitAudioContext)()}catch{}}if(audio.ctx?.state==='suspended')audio.ctx.resume()}
const audio={ctx:null,play(freq=150,duration=.08,kind='square',volume=.035){if(!this.ctx)return;try{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=kind;o.frequency.setValueAtTime(freq,this.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.45),this.ctx.currentTime+duration);g.gain.setValueAtTime(volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}catch{}}};
function announce(text,seconds=2.5){$('#notice').textContent=text;$('#notice').classList.add('show');noticeTime=seconds}

