import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const $=s=>document.querySelector(s), root=$('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x858a82);
scene.fog=new THREE.FogExp2(0x858a82,.009);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,220);
const renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'high-performance'});
renderer.setSize(innerWidth,innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.15;
root.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc3ccd0,0x3c4033,1.6));
const sun=new THREE.DirectionalLight(0xffddb1,2.1);
sun.position.set(-35,52,22);scene.add(sun);
const mat=(c,r=.9,m=0)=>new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:m});
const M={ground:mat(0x4b4d3e),mud:mat(0x38382f),wood:mat(0x51483a),woodLight:mat(0x716148),stone:mat(0x62645c),dark:mat(0x292d2a),metal:mat(0x464b48,.58,.55),sand:mat(0x82775e),cloth:mat(0x4a4b40),leaf:mat(0x303a30),fire:mat(0xff7c2d),smoke:new THREE.MeshBasicMaterial({color:0x50534f,transparent:true,opacity:.2,depthWrite:false}),rain:new THREE.LineBasicMaterial({color:0xbac5c7,transparent:true,opacity:.28})};
const box=new THREE.BoxGeometry(1,1,1),sphere=new THREE.SphereGeometry(1,10,8),cylinder=new THREE.CylinderGeometry(.5,.5,1,8);
function add(geo,material,x,y,z,sx=1,sy=sx,sz=sx){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);scene.add(o);return o}
const colliders=[];
function obstacle(x,z,w,h,d,material=M.wood,rot=0){const o=add(box,material,x,h/2,z,w,h,d);o.rotation.y=rot;colliders.push({x,z,w,d});return o}
// Muddy battlefield and the low stone defenses around a ruined outpost.
add(box,M.ground,0,-.32,0,110,.6,110);
add(box,M.mud,0,-.015,-8,7,.035,86);
for(let i=0;i<42;i++){const x=(Math.random()-.5)*96,z=(Math.random()-.5)*96;if(Math.abs(x)<4&&z<35&&z>-48)continue;const s=.15+Math.random()*.55;add(sphere,i%3?M.mud:M.sand,x,.015,z,s,.05+Math.random()*.1,s*1.6)}
// Defensive sandbag walls and broken timber positions.
for(const [x,z,n,axis] of [[-8,-10,8,0],[8,-13,7,0],[-13,3,7,Math.PI/2],[13,4,8,Math.PI/2],[-7,19,7,0],[9,21,6,0]]){for(let i=0;i<n;i++){let px=x+(axis?0:(i-(n-1)/2)*.82),pz=z+(axis?(i-(n-1)/2)*.82:0);let b=add(box,M.sand,px,.28,pz,.9,.52,.62);b.rotation.y=axis?Math.PI/2:0;if(i===Math.floor(n/2))colliders.push({x:px,z:pz,w:axis?.7:.88,d:axis?.88:.7})}}
for(const [x,z,w,d,a] of [[-22,-12,9,1,0],[21,-16,11,1,0],[-25,12,1,12,0],[27,14,1,15,0],[-9,31,16,1,0],[12,33,12,1,0]]){let o=obstacle(x,z,w,.8,d,M.wood,a);for(let i=0;i<3;i++){let plank=add(box,M.woodLight,x+(Math.random()-.5)*w,.9+Math.random()*.7,z+(Math.random()-.5)*d,.12,1.8,.13);plank.rotation.z=(Math.random()-.5)*.24}}
// Ruined houses and distant silhouettes, kept simple for real-time rendering.
function ruinedHouse(x,z,w,d){obstacle(x,z,w,2.3,d,M.stone);add(box,M.dark,x,2.4,z,w*.76,.18,d*.7);for(let i=0;i<4;i++){let beam=add(box,M.wood,x+(i-1.5)*w*.22,2.1,z-d*.48,.18,2.1,.2);beam.rotation.z=(Math.random()-.5)*.2}add(box,M.dark,x,1.2,z-d*.505,w*.32,1.5,.04)}
ruinedHouse(-34,-18,8,7);ruinedHouse(36,25,9,8);ruinedHouse(-38,32,7,8);
function tree(x,z,h){let trunk=add(cylinder,M.wood,x,h*.28,z,.48,h*.56,.48);trunk.rotation.z=(Math.random()-.5)*.16;for(let i=0;i<3;i++)add(sphere,M.leaf,x+(Math.random()-.5)*1.4,h*.58+i*h*.13,z+(Math.random()-.5)*1.2,h*.2,h*.22,h*.2);colliders.push({x,z,w:1,d:1})}
for(let i=0;i<40;i++){let x=(Math.random()-.5)*100,z=(Math.random()-.5)*100;if(Math.hypot(x,z)<25)continue;tree(x,z,4+Math.random()*4)}
const view=new THREE.Group();camera.add(view);scene.add(camera);
const armMat=mat(0x77705e),gunMat=mat(0x292d2d,.55,.72),woodMat=mat(0x554435),sleeve=add(box,armMat,.3,-.28,-.48,.22,.24,.5);sleeve.parent=view;scene.remove(sleeve);
const gun=new THREE.Group();view.add(gun);gun.position.set(.32,-.28,-.72);
const gunBody=add(box,gunMat,0,0,0,.13,.14,.7);gun.add(gunBody);scene.remove(gunBody);
const stock=add(box,woodMat,0,-.015,.38,.16,.17,.36);gun.add(stock);scene.remove(stock);
const barrel=add(cylinder,gunMat,0,.015,-.52,.045,.58,.045);barrel.rotation.x=Math.PI/2;gun.add(barrel);scene.remove(barrel);
const grip=add(box,woodMat,0,-.14,.08,.09,.24,.12);grip.rotation.x=-.2;gun.add(grip);scene.remove(grip);
const sleeveMesh=new THREE.Mesh(box,armMat);sleeveMesh.position.set(.27,-.25,-.2);sleeveMesh.scale.set(.2,.2,.4);view.add(sleeveMesh);
const fires=[],smoke=[];
for(const [x,z] of [[-32,3],[30,-28],[2,38]]){const f=add(sphere,M.fire,x,.4,z,.22,.38,.22);const l=new THREE.PointLight(0xff7735,2.2,9);l.position.set(x,.8,z);scene.add(l);fires.push({f,l});for(let i=0;i<5;i++){let s=add(sphere,M.smoke,x+(Math.random()-.5)*.5,1+i*.7,z+(Math.random()-.5)*.5,.45+i*.08,.55+i*.1,.45+i*.08);smoke.push(s)}}
const rainN=650,rainGeo=new THREE.BufferGeometry(),rainPositions=new Float32Array(rainN*3);for(let i=0;i<rainN;i++){rainPositions[i*3]=(Math.random()-.5)*95;rainPositions[i*3+1]=Math.random()*25;rainPositions[i*3+2]=(Math.random()-.5)*95}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));const rain=new THREE.LineSegments(rainGeo,M.rain);scene.add(rain);

